import {normalizeFeed,filtered,amapLink,toWgs84} from './food-core.js';
const $=id=>document.getElementById(id);const state={rows:[],map:null,markers:[],active:null};
function element(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}
function link(text,url){const node=element('a',text);node.href=url;node.target='_blank';node.rel='noopener noreferrer';return node;}
function matches(){return filtered(state.rows,$('search').value,$('city').value,$('category').value);}
function popup(p){const box=element('div');box.append(element('h3',p.name),element('p',p.city+' · '+p.category),element('p',p.address||'Check the original venue listing.'),link('Open in Amap ↗',amapLink(p)));if(p.articleUrl)box.append(element('br'),link('Original recommendation ↗',p.articleUrl));return box;}
function select(p){state.active=p.id;document.querySelectorAll('.venue-card').forEach(c=>c.classList.toggle('selected',c.dataset.id===p.id));if(state.map){state.map.setView(toWgs84(p.lng,p.lat),15);const marker=state.markers.find(m=>m.venueId===p.id);if(marker)marker.openPopup();}else{$('map-status').textContent='Selected: '+p.name+'. Load the map to see its marker.';}}
function markers(){if(!state.map)return;state.markers.forEach(m=>m.remove());state.markers=[];for(const p of matches()){const marker=L.circleMarker(toWgs84(p.lng,p.lat),{radius:8,color:'#fcfcf8',weight:2,fillColor:'#466f7f',fillOpacity:.95}).addTo(state.map).bindPopup(popup(p));marker.venueId=p.id;marker.on('click',()=>select(p));state.markers.push(marker);}}
function fit(){if(state.map&&state.markers.length)state.map.fitBounds(L.featureGroup(state.markers).getBounds(),{padding:[40,40],maxZoom:13});}
function render(){const rows=matches();$('result-count').textContent=`${rows.length} ${rows.length===1?'place':'places'} to explore`;$('results').replaceChildren();if(!rows.length)$('results').append(element('p','No matching places. Try another city or reset the filters.','empty-state'));for(const p of rows){const card=element('article',undefined,'venue-card');card.dataset.id=p.id;const top=element('div',undefined,'venue-top');top.append(element('span',p.city),element('span',p.category));const actions=element('div',undefined,'venue-actions');const button=element('button','Show on map');button.type='button';button.addEventListener('click',()=>select(p));actions.append(button,link('Amap ↗',amapLink(p)));if(p.articleUrl)actions.append(link('Original ↗',p.articleUrl));card.append(top,element('h2',p.name),element('p',p.address||'Address details in the original listing.'),actions);$('results').append(card);}markers();}
async function loadMap(){const button=$('load-map');button.disabled=true;button.textContent='Loading the map…';try{if(!window.L)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/assets/vendor/leaflet.js';script.onload=resolve;script.onerror=()=>reject(new Error('Map library unavailable'));document.head.append(script);});$('map').replaceChildren();state.map=L.map('map',{scrollWheelZoom:false}).setView([34.3,108.9],4);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',updateWhenIdle:true,keepBuffer:1}).addTo(state.map).on('tileerror',()=>{$('map-status').textContent='Some map tiles are unavailable; the venue list and Amap links still work.';});markers();fit();$('map-status').textContent='Approximate WGS84 markers · source coordinates remain GCJ-02';$('fit-map').hidden=false;if(state.active){const p=state.rows.find(p=>p.id===state.active);if(p)select(p);}}catch(error){$('map-status').textContent='The map could not load. The venue list and Amap links remain available.';if(button.isConnected){button.disabled=false;button.textContent='Try loading the map again';}}}
async function load(){try{const response=await fetch('/data/food.json');if(!response.ok)throw new Error('Collection unavailable');const data=await response.json();state.rows=normalizeFeed(data);$('total-count').textContent=state.rows.length;const date=new Date(data.retrievedAt);$('updated').textContent=Number.isNaN(date.valueOf())?'Public source · CacheTide':`Source changed ${date.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}`;for(const [id,values] of [['city',[...new Set(state.rows.map(p=>p.city))].sort()],['category',[...new Set(state.rows.map(p=>p.category))].sort()]])for(const value of values){const option=element('option',value);option.value=value;$(id).append(option);}render();}catch(error){$('result-count').textContent='Collection temporarily unavailable';$('updated').textContent='No private or fabricated data was substituted.';$('results').replaceChildren(element('p','The public collection could not be loaded. Please return later or visit the original source.','empty-state'));}}
$('search').addEventListener('input',render);$('city').addEventListener('change',()=>{render();fit();});$('category').addEventListener('change',()=>{render();fit();});$('reset').addEventListener('click',()=>{$('search').value='';$('city').value='';$('category').value='';render();fit();});$('load-map').addEventListener('click',loadMap);$('fit-map').addEventListener('click',fit);load();
